from jinja2 import Environment

env = Environment(trim_blocks=True, lstrip_blocks=True)
t = env.from_string("""{% set ns = namespace(total=0) %}
{% for u in users if u.active %}
  {{ loop.index }}/{{ loop.length }} {{ u.name }}{{ " (first)" if loop.first }}
  {% set ns.total = ns.total + u.score %}
{% else %}
  No active users.
{% endfor %}
Total: {{ ns.total }}
{% for k, v in limits.items() %}{{ k }}={{ v }}{{ "," if not loop.last }}{% endfor %}""")

print(t.render(users=[{"name": "Ann", "active": True, "score": 3},
                      {"name": "Bo", "active": False, "score": 9},
                      {"name": "Cy", "active": True, "score": 4}],
               limits={"cpu": 2, "mem": "1Gi"}))
#   1/2 Ann (first)
#   2/2 Cy
# Total: 7
# cpu=2,mem=1Gi

from jinja2 import DictLoader, Environment

env = Environment(autoescape=True, trim_blocks=True, lstrip_blocks=True, loader=DictLoader({
    "ui.html": """{% macro field(name, label, type="text") -%}
<label>{{ label }} <input name="{{ name }}" type="{{ type }}"></label>
{%- endmacro %}
{% macro card(title) -%}
<div class="card"><h2>{{ title }}</h2>{{ caller() }}</div>
{%- endmacro %}""",
    "nav.html": "<nav>Hi {{ user }}</nav>",
    "page.html": """{% import "ui.html" as ui %}
{% include "nav.html" %}
{% call ui.card("Sign up") %}{{ ui.field("email", "Email", type="email") }}{% endcall %}""",
}))
print(env.get_template("page.html").render(user="Ann"))
# <nav>Hi Ann</nav><div class="card"><h2>Sign up</h2><label>Email <input name="email" type="email"></label></div>
